const http = require('http')
const fs = require('fs')
const path = require('path')

const PORT = 3000
const OLLAMA_URL = 'http://localhost:11434'

const MIME_TYPES = {
  '.html': 'text/html',
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon'
}

const server = http.createServer((req, res) => {
  // Handle API proxy
  if (req.url.startsWith('/api/')) {
    proxyToOllama(req, res)
    return
  }

  // Serve static files
  let filePath = path.join(__dirname, 'dist', req.url === '/' ? 'index.html' : req.url)

  const ext = path.extname(filePath)
  const contentType = MIME_TYPES[ext] || 'application/octet-stream'

  fs.readFile(filePath, (err, content) => {
    if (err) {
      if (err.code === 'ENOENT') {
        // Fallback to index.html for SPA routing
        fs.readFile(path.join(__dirname, 'dist', 'index.html'), (err2, content2) => {
          if (err2) {
            res.writeHead(404)
            res.end('File not found')
          } else {
            res.writeHead(200, { 'Content-Type': 'text/html' })
            res.end(content2)
          }
        })
      } else {
        res.writeHead(500)
        res.end('Server error')
      }
    } else {
      res.writeHead(200, { 'Content-Type': contentType })
      res.end(content)
    }
  })
})

function proxyToOllama(req, res) {
  const url = req.url.replace('/api/', OLLAMA_URL + '/')
  const options = {
    hostname: 'localhost',
    port: 11434,
    path: req.url,
    method: req.method,
    headers: {
      'Content-Type': 'application/json'
    }
  }

  const proxyReq = http.request(options, (proxyRes) => {
    res.writeHead(proxyRes.statusCode, proxyRes.headers)
    proxyRes.pipe(res)
  })

  proxyReq.on('error', (e) => {
    res.writeHead(500)
    res.end(JSON.stringify({ error: e.message }))
  })

  if (req.method !== 'GET') {
    let body = ''
    req.on('data', chunk => { body += chunk })
    req.on('end', () => {
      if (body) {
        proxyReq.write(body)
      }
      proxyReq.end()
    })
  } else {
    proxyReq.end()
  }
}

server.listen(PORT, () => {
  console.log(`Ollama Web UI running at http://localhost:${PORT}`)
  console.log(`Proxying API requests to ${OLLAMA_URL}`)
})

