const express = require('express')
const cors = require('cors')
const http = require('http')
require('dotenv').config()

const app = express()
const PORT = process.env.PORT || 4000
const OLLAMA_URL = process.env.OLLAMA_URL || 'http://localhost:11434'
const ANTHROPIC_URL = process.env.ANTHROPIC_URL || 'https://api.anthropic.com'
const ANTHROPIC_API_KEY = process.env.ANTHROPIC_API_KEY

app.use(cors())
app.use(express.json())

// Unified chat endpoint - routes to Ollama or Anthropic based on model
app.post('/v1/chat/completions', async (req, res) => {
  const { model, messages, stream = false } = req.body

  // Check if it's an Ollama model or Anthropic model
  if (model.includes('ollama') || isLocalModel(model)) {
    return routeToOllama(req, res, model, messages, stream)
  } else if (model.includes('claude')) {
    return routeToAnthropic(req, res, model, messages, stream)
  } else {
    return res.status(400).json({ error: `Unknown model: ${model}` })
  }
})

// Direct Ollama proxy
app.all('/ollama/*', async (req, res) => {
  const path = req.url.replace('/ollama', '')
  const options = {
    hostname: new URL(OLLAMA_URL).hostname,
    port: new URL(OLLAMA_URL).port || 11434,
    path: path,
    method: req.method,
    headers: {
      'Content-Type': 'application/json'
    }
  }

  const proxyReq = http.request(options, (proxyRes) => {
    res.writeHead(proxyRes.statusCode, proxyRes.headers)
    proxyRes.pipe(res)
  })

  proxyReq.on('error', (e) => {
    res.status(500).json({ error: e.message })
  })

  if (req.method !== 'GET') {
    let body = ''
    req.on('data', chunk => { body += chunk })
    req.on('end', () => {
      if (body) proxyReq.write(body)
      proxyReq.end()
    })
  } else {
    proxyReq.end()
  }
})

// Direct Anthropic proxy
app.all('/anthropic/*', async (req, res) => {
  if (!ANTHROPIC_API_KEY || ANTHROPIC_API_KEY === 'your_api_key_here') {
    return res.status(401).json({
      error: 'Anthropic API key not configured. Set ANTHROPIC_API_KEY in .env file.'
    })
  }

