    hostname: new URL(ANTHROPIC_URL).hostname,
    port: 443,
    path: path,
    method: req.method,
    headers: {
      'Content-Type': 'application/json',
      'x-api-key': ANTHROPIC_API_KEY,
      'anthropic-version': '2023-06-01'
    }
  }

