function isLocalModel(modelName) {
  const localModels = [
    'qwen', 'llama', 'codellama', 'deepseek', 'glm', 'nemotron',
    'supergemma', 'gemma', 'mistral', 'mixtral'
  ]
  return localModels.some(m => modelName.toLowerCase().includes(m))
}

async function routeToOllama(req, res, model, messages, stream) {
  try {
    const cleanModel = model.replace('ollama://', '')
    const response = await fetch(`${OLLAMA_URL}/api/chat`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        model: cleanModel,
        messages: messages.map(m => ({
          role: m.role,
          content: m.content
        })),
        stream: false
      })
    })

    if (!response.ok) {
      const error = await response.text()
      return res.status(response.status).json({ error })
    }

    const data = await response.json()
    res.json({
      id: `ollama-${Date.now()}`,
      object: 'chat.completion',
      created: Date.now(),
      model: cleanModel,
      choices: [{
        index: 0,
        message: {
          role: 'assistant',
          content: data.message?.content || ''
        },
        finish_reason: 'stop'
      }],
      usage: {
        prompt_tokens: 0,
        completion_tokens: 0,
        total_tokens: 0
      }
    })
  } catch (error) {
    res.status(500).json({ error: error.message })
  }
}

async function routeToAnthropic(req, res, model, messages, stream) {
  if (!ANTHROPIC_API_KEY || ANTHROPIC_API_KEY === 'your_api_key_here') {
    return res.status(401).json({
      error: 'Anthropic API key not configured'
    })
  }

  try {
    // Convert OpenAI format to Anthropic format
    const systemMessage = messages.find(m => m.role === 'system')
    const otherMessages = messages.filter(m => m.role !== 'system')

    const response = await fetch(`${ANTHROPIC_URL}/v1/messages`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: model.replace('claude-', 'claude-'),
        max_tokens: 4096,
        system: systemMessage?.content,
        messages: otherMessages.map(m => ({
          role: m.role === 'assistant' ? 'assistant' : 'user',
          content: m.content
        }))
      })
    })

    if (!response.ok) {
      const error = await response.text()
      return res.status(response.status).json({ error })
    }

    const data = await response.json()
    res.json({
      id: data.id,
      object: 'chat.completion',
      created: Date.now(),
      model: model,
      choices: [{
        index: 0,
        message: {
          role: 'assistant',
          content: data.content?.[0]?.text || ''
        },
        finish_reason: 'stop'
      }],
      usage: data.usage
    })
  } catch (error) {
    res.status(500).json({ error: error.message })
  }
}

